import cv2
import numpy as np
import glob
import os

frames = sorted(glob.glob('/root/keyframes_*.png'))

templates = {
    'coins': '/root/coin.png',
    'enemies': '/root/enemy.png',
    'turtles': '/root/turtle.png',
}

THRESHOLD = 0.9
DEDUP_MIN_DIST = 3


def load_gray(path):
    img = cv2.imread(path, cv2.IMREAD_GRAYSCALE)
    if img is None:
        raise FileNotFoundError(path)
    return img


def count_matches(frame_gray, template_gray):
    if frame_gray.shape[0] < template_gray.shape[0] or frame_gray.shape[1] < template_gray.shape[1]:
        return 0
    res = cv2.matchTemplate(frame_gray, template_gray, cv2.TM_CCOEFF_NORMED)
    ys, xs = np.where(res >= THRESHOLD)
    if len(xs) == 0:
        return 0
    scores = res[ys, xs]
    order = np.argsort(-scores)
    picked = []
    for idx in order:
        x = int(xs[idx])
        y = int(ys[idx])
        keep = True
        for (px, py) in picked:
            if (x - px) ** 2 + (y - py) ** 2 <= DEDUP_MIN_DIST ** 2:
                keep = False
                break
        if keep:
            picked.append((x, y))
    return len(picked)

# Load templates once
template_grays = {k: load_gray(v) for k, v in templates.items()}

results = []
for frame in frames:
    frame_gray = load_gray(frame)
    counts = {}
    for key, timg in template_grays.items():
        counts[key] = count_matches(frame_gray, timg)
    results.append((frame, counts['coins'], counts['enemies'], counts['turtles']))

# Write CSV
out_path = '/root/counting_results.csv'
with open(out_path, 'w', encoding='utf-8') as f:
    f.write('frame_id,coins,enemies,turtles\n')
    for frame, c, e, t in results:
        f.write(f'{frame},{c},{e},{t}\n')

print(out_path)
print('\n'.join([f"{os.path.basename(r[0])}: coins={r[1]}, enemies={r[2]}, turtles={r[3]}" for r in results]))
